# generates fq_draw.s : FastQuake 486 span drawers with FDIV overlap
hdr = r'''//
// fq_draw.s: FastQuake 486 span drawers (LFTech). GPL v2.
// Perspective-correct spans with 32 or 64 pixel segments. The FDIV for the
// end of the next segment runs while the current segment is drawn (the 486
// FPU lets integer code run during FDIV), like id's d_draw16.s.
// Generated by tools/genspan.py.
//
#include "asm_i386.h"
#include "quakeasm.h"
#include "asm_draw.h"
#include "d_ifacea.h"

	.data
	.align 4
.globl C(fq_sdivzN), C(fq_tdivzN), C(fq_ziN)
C(fq_sdivzN):	.single 0
C(fq_tdivzN):	.single 0
C(fq_ziN):		.single 0
fqa_s:		.long 0
fqa_t:		.long 0
fqa_snext:	.long 0
fqa_tnext:	.long 0
fqa_count:	.long 0
fqa_m:		.long 0
fqa_pspan:	.long 0
fqa_pdest:	.long 0
fqa_seg:	.long 0
fqa_adv:	.long 0, 0
fqa_tstep:	.long 0
fqa_64k:	.single 65536.0

	.text

// draw ecx (1..64) pixels: edi = pdest, esi = psrc, ebx = sfrac,
// edx = tfrac, ebp = sstep frac; fqa_tstep, fqa_adv set. Clobbers eax, ecx, edi
#define PIX(i) \
	movb	(%esi),%al ; \
	addl	fqa_tstep,%edx ; \
	sbbl	%ecx,%ecx ; \
	addl	%ebp,%ebx ; \
	adcl	fqa_adv+4(,%ecx,4),%esi ; \
	movb	%al,i(%edi)

	.align 4
LDrawPix:
	movl	%ecx,%eax
	subl	$64,%eax
	addl	%eax,%edi
	jmp		*LEntry(,%ecx,4)
'''
pix = ''.join('LP%d:\tPIX(%d)\n' % (i, i) for i in range(64)) + '\tret\n\n'
entry = '\t.data\n\t.align 4\nLEntry:\n\t.long LP63\n' + ''.join('\t.long LP%d\n' % (64 - c) for c in range(1, 65)) + '\t.text\n'

body = r'''
//----------------------------------------------------------------------
// void D_DrawSpansFQ@N@ (espan_t *pspan)
//----------------------------------------------------------------------
	.align 4
.globl C(D_DrawSpansFQ@N@)
C(D_DrawSpansFQ@N@):
	pushl	%ebp
	pushl	%edi
	pushl	%esi
	pushl	%ebx
	movl	20(%esp),%ebx

L@N@SpanLoop:
	movl	%ebx,fqa_pspan
	// s/z, t/z, 1/z at the start of the span (as in d_draw16.s)
	fildl	espan_t_v(%ebx)
	fildl	espan_t_u(%ebx)
	fld		%st(1)
	fmuls	C(d_sdivzstepv)
	fld		%st(1)
	fmuls	C(d_sdivzstepu)
	fld		%st(2)
	fmuls	C(d_tdivzstepu)
	fxch	%st(1)
	faddp	%st(0),%st(2)
	fxch	%st(1)
	fld		%st(3)
	fmuls	C(d_tdivzstepv)
	fxch	%st(1)
	fadds	C(d_sdivzorigin)
	fxch	%st(4)
	fmuls	C(d_zistepv)
	fxch	%st(1)
	faddp	%st(0),%st(2)
	fxch	%st(2)
	fmuls	C(d_zistepu)
	fxch	%st(1)
	fadds	C(d_tdivzorigin)
	fxch	%st(2)
	faddp	%st(0),%st(1)
	flds	fqa_64k
	fxch	%st(1)
	fadds	C(d_ziorigin)
	fdivr	%st(0),%st(1)		// 1/z | z*64k | t/z | s/z

	movl	C(d_viewbuffer),%ecx
	movl	espan_t_v(%ebx),%eax
	movl	C(d_scantable)(,%eax,4),%edi
	addl	%ecx,%edi
	addl	espan_t_u(%ebx),%edi
	movl	%edi,fqa_pdest
	movl	espan_t_count(%ebx),%ecx
	movl	%ecx,fqa_count

	fxch	%st(1)				// z | 1/z | t/z | s/z
	fld		%st(0)
	fmul	%st(4),%st(0)		// s | z | 1/z | t/z | s/z
	fxch	%st(1)
	fmul	%st(3),%st(0)		// t | s | 1/z | t/z | s/z
	fxch	%st(1)
	fistpl	fqa_s
	fistpl	fqa_t				// 1/z | t/z | s/z

	movl	fqa_s,%eax
	addl	C(sadjust),%eax
	cmpl	C(bbextents),%eax
	jbe		L@N@s0ok
	jl		L@N@s0lo
	movl	C(bbextents),%eax
	jmp		L@N@s0ok
L@N@s0lo:
	xorl	%eax,%eax
L@N@s0ok:
	movl	%eax,fqa_s
	movl	fqa_t,%eax
	addl	C(tadjust),%eax
	cmpl	C(bbextentt),%eax
	jbe		L@N@t0ok
	jl		L@N@t0lo
	movl	C(bbextentt),%eax
	jmp		L@N@t0ok
L@N@t0lo:
	xorl	%eax,%eax
L@N@t0ok:
	movl	%eax,fqa_t

	cmpl	$1,%ecx
	je		L@N@OnePixel

	// start the FDIV for the end of the first segment
	call	L@N@Advance

L@N@SegLoop:
	// FP: z | 1/z | t/z | s/z at the end of this segment
	fld		%st(0)
	fmul	%st(4),%st(0)
	fxch	%st(1)
	fmul	%st(3),%st(0)
	fxch	%st(1)
	fistpl	fqa_snext
	fistpl	fqa_tnext			// 1/z | t/z | s/z

	movl	fqa_snext,%eax
	addl	C(sadjust),%eax
	cmpl	$4096,%eax
	jge		1f
	movl	$4096,%eax
1:	cmpl	C(bbextents),%eax
	jle		1f
	movl	C(bbextents),%eax
1:	movl	%eax,fqa_snext
	movl	fqa_tnext,%ebx
	addl	C(tadjust),%ebx
	cmpl	$4096,%ebx
	jge		1f
	movl	$4096,%ebx
1:	cmpl	C(bbextentt),%ebx
	jle		1f
	movl	C(bbextentt),%ebx
1:	movl	%ebx,fqa_tnext

	subl	fqa_s,%eax			// eax = snext - s
	subl	fqa_t,%ebx			// ebx = tnext - t
	movl	fqa_count,%ecx
	cmpl	$@N@,%ecx
	jbe		L@N@LastSeg
	sarl	$@SH@,%eax
	sarl	$@SH@,%ebx
	movl	%eax,%ebp			// sstep
	movl	%ebx,%edx			// tstep
	movl	$@N@,fqa_seg
	subl	$@N@,%ecx
	movl	%ecx,fqa_count
	jmp		L@N@Steps

L@N@LastSeg:
	movl	%ecx,fqa_seg
	movl	$0,fqa_count
	decl	%ecx				// count-1 >= 1
	cmpl	$1,%ecx
	je		1f
	movl	%ecx,fqa_m
	cltd
	idivl	fqa_m
	movl	%eax,%ebp			// sstep
	movl	%ebx,%eax
	cltd
	idivl	fqa_m
	movl	%eax,%edx			// tstep
	jmp		L@N@Steps
1:	movl	%eax,%ebp
	movl	%ebx,%edx

L@N@Steps:
	// advancetable from the integer parts of the steps
	movl	%edx,%eax
	movl	%ebp,%ecx
	sarl	$16,%eax
	sarl	$16,%ecx
	imull	C(cachewidth),%eax
	addl	%ecx,%eax
	movl	%eax,fqa_adv+4
	addl	C(cachewidth),%eax
	movl	%eax,fqa_adv
	shll	$16,%edx
	shll	$16,%ebp
	movl	%edx,fqa_tstep

	// more after this segment? start that FDIV now so it overlaps
	movl	fqa_count,%ecx
	cmpl	$1,%ecx
	jbe		1f
	call	L@N@Advance
1:
	// psource = pbase + (s >> 16) + (t >> 16) * cachewidth
	movl	fqa_t,%eax
	movl	fqa_s,%esi
	sarl	$16,%eax
	sarl	$16,%esi
	imull	C(cachewidth),%eax
	addl	C(cacheblock),%esi
	addl	%eax,%esi
	movl	fqa_s,%ebx
	movl	fqa_t,%edx
	shll	$16,%ebx
	shll	$16,%edx
	movl	fqa_pdest,%edi
	movl	fqa_seg,%ecx
	addl	%ecx,fqa_pdest
	call	LDrawPix

	movl	fqa_snext,%eax
	movl	fqa_tnext,%ebx
	movl	%eax,fqa_s
	movl	%ebx,fqa_t
	movl	fqa_count,%ecx
	cmpl	$1,%ecx
	ja		L@N@SegLoop
	jb		L@N@SpanDone

L@N@OnePixel:
	// one pixel at s,t
	movl	fqa_t,%eax
	movl	fqa_s,%esi
	sarl	$16,%eax
	sarl	$16,%esi
	imull	C(cachewidth),%eax
	addl	C(cacheblock),%esi
	movb	(%esi,%eax),%al
	movl	fqa_pdest,%edi
	movb	%al,(%edi)

L@N@SpanDone:
	fstp	%st(0)
	fstp	%st(0)
	fstp	%st(0)
	movl	fqa_pspan,%ebx
	movl	espan_t_pnext(%ebx),%ebx
	testl	%ebx,%ebx
	jnz		L@N@SpanLoop

	popl	%ebx
	popl	%esi
	popl	%edi
	popl	%ebp
	ret

// advance 1/z, t/z, s/z to the end of the next segment (ecx = pixels left,
// >= 2) and start the FDIV:  1/z | t/z | s/z  ->  z | 1/z | t/z | s/z
L@N@Advance:
	cmpl	$@N@,%ecx
	jbe		1f
	fadds	C(fq_ziN)
	fxch	%st(2)
	fadds	C(fq_sdivzN)
	fxch	%st(2)
	flds	C(fq_tdivzN)
	faddp	%st(0),%st(2)
	flds	fqa_64k
	fdiv	%st(1),%st(0)
	ret
1:	decl	%ecx
	movl	%ecx,fqa_m
	fildl	fqa_m				// m | 1/z | t/z | s/z
	flds	C(d_zistepu)
	fmul	%st(1),%st(0)
	faddp	%st(0),%st(2)		// m | 1/z' | t/z | s/z
	flds	C(d_tdivzstepu)
	fmul	%st(1),%st(0)
	faddp	%st(0),%st(3)		// m | 1/z' | t/z' | s/z
	fmuls	C(d_sdivzstepu)
	faddp	%st(0),%st(3)		// 1/z' | t/z' | s/z'
	flds	fqa_64k
	fdiv	%st(1),%st(0)
	ret
'''
out = hdr + pix + entry
for N, SH in ((32, 5), (64, 6)):
    out += body.replace('@N@', str(N)).replace('@SH@', str(SH))
open(__import__('sys').argv[1] if len(__import__('sys').argv) > 1 else 'fq_draw.s', 'w').write(out)
